import { join } from "path";

export interface AppConfig {
  /** pushq 상태 디렉토리(PUSHQ_HOME) */
  pushqHome: string;
  /** pushq 바이너리 경로 */
  pushqBin: string;
  /** 출금 실패 후 재출금까지 걸리는 시간(분) */
  retryDelayMinutes: number;
  /** 재출금 안내를 재출금 몇 분 전에 보낼지 */
  retryNoticeLeadMinutes: number;
  /** 야간 방해 금지 구간 [시작, 끝) — "HH:MM" */
  quietStart: string;
  quietEnd: string;
  /** 방해 금지 구간에 걸린 알림을 옮길 전날 저녁 시각 */
  quietFallback: string;
  /** 고객이 고를 수 있는 출금 예정 알림 시점(분) */
  allowedLeads: number[];
}

export function loadConfig(overrides: Partial<AppConfig> = {}): AppConfig {
  return {
    pushqHome: process.env.PUSHQ_HOME ?? join(process.cwd(), ".pushq"),
    pushqBin: join(process.cwd(), "vendor", "bin", "pushq"),
    retryDelayMinutes: 120,
    retryNoticeLeadMinutes: 30,
    quietStart: "22:00",
    quietEnd: "07:00",
    quietFallback: "21:00",
    allowedLeads: [10, 30, 60, 1440],
    ...overrides,
  };
}
---APP
import { mountAccountRoutes, mountReminderRoutes } from "./api/routes";
import { Response, Router } from "./api/router";
import { AppConfig, loadConfig } from "./config";
import { PushqClient } from "./push/pushqClient";
import { ReminderReportBuilder } from "./report/reminderReport";
import { AutopayRepository } from "./repository/autopayRepository";
import { MemberRepository } from "./repository/memberRepository";
import { ReminderRepository } from "./repository/reminderRepository";
import { QuietHours } from "./scheduling/quietHours";
import { SendTimePolicy } from "./scheduling/sendTime";
import { ReminderPlanner } from "./service/reminderPlanner";
import { ReminderService } from "./service/reminderService";

export interface App {
  config: AppConfig;
  handle(method: string, url: string, body?: unknown): Response;
}

export function createApp(overrides: Partial<AppConfig> = {}): App {
  const config = loadConfig(overrides);
  const members = new MemberRepository();
  const autopays = new AutopayRepository();
  const reminders = new ReminderRepository();
  const push = new PushqClient(config.pushqBin, config.pushqHome);
  const policy = new SendTimePolicy(new QuietHours(config.quietStart, config.quietEnd, config.quietFallback));
  const planner = new ReminderPlanner(members, autopays, policy, config.retryNoticeLeadMinutes);
  const service = new ReminderService(planner, autopays, reminders, push, config.retryDelayMinutes);
  const report = new ReminderReportBuilder(reminders, push);

  const router = new Router();
  mountAccountRoutes(router, config, members, autopays);
  mountReminderRoutes(router, service, report, members, push);
  return { config, handle: (m, u, b) => router.handle(m, u, b) };
}
---TIMETEST
import { QuietHours } from "../src/scheduling/quietHours";
import { SendTimePolicy } from "../src/scheduling/sendTime";
import { addMinutes, at, compare, isLocalDateTime, previousDate } from "../src/time/localTime";
import { eq, run, test } from "./harness";

test("minute arithmetic crosses days, months and leap days", () => {
  eq(addMinutes("2026-10-12T00:10:00", -30), "2026-10-11T23:40:00", "back over midnight");
  eq(addMinutes("2026-11-01T09:00:00", -1440), "2026-10-31T09:00:00", "back over month end");
  eq(addMinutes("2028-02-28T23:30:00", 60), "2028-02-29T00:30:00", "leap day");
  eq(previousDate("2026-01-01"), "2025-12-31", "previous date over year end");
});

test("local time validation rejects impossible dates", () => {
  eq(isLocalDateTime("2026-02-30T10:00:00"), false, "Feb 30");
  eq(isLocalDateTime("2026-10-12T24:00:00"), false, "hour 24");
  eq(isLocalDateTime("2026-10-12 10:00:00"), false, "space separator");
  eq(isLocalDateTime("2026-10-12T10:00:59"), true, "valid");
  eq(compare(at("2026-10-12", "10:20"), "2026-10-12T10:19:59") > 0, true, "ordering");
});

test("quiet hours pull a reminder back to the previous evening", () => {
  const policy = new SendTimePolicy(new QuietHours("22:00", "07:00", "21:00"));
  eq(policy.sendAt("2026-10-12T07:00:00", 60), "2026-10-11T21:00:00", "06:00 → evening before");
  eq(policy.sendAt("2026-10-12T23:30:00", 30), "2026-10-12T21:00:00", "23:00 → same evening");
  eq(policy.sendAt("2026-10-12T09:00:00", 30), "2026-10-12T08:30:00", "daytime unchanged");
  eq(policy.sendAt("2026-10-12T07:10:00", 10), "2026-10-12T07:00:00", "quiet end is exclusive");
});

run();

